import xmltodict

from lxml import etree

from .exceptions import InvalidDictPath, SoapApiError, UnexpectedResponse


def process_response(response, result_path='result', return_path=None,
                     require_unique=True):
    """
    Parse API response

    :param dict(string, string) response:
    :param string result_path: path to dictionary element needed. For example, if:

        >> result_path = 'managedObjectDefs.managedObjectDef'
        then
        >> output = response['result']['managedObjectDefs']['managedObjectDef']

    :param string return_path: if single object is returned instead of list - path to dictionary element
        inside of given object. For example, if:

        >> result_path = 'batchItemMOLiteResult'
        >> return_path = 'moLite'
        then
        >> output = response['result']['batchItemMOLiteResult'][0]['moLite']

    :param bool require_unique: can be used to return a single object instead of list.
        If True and output is a list - only the first element is returned.
        If list has more than one element - UnexpectedResponseException is raised.
    :return: parsed API response
    :rtype: (list | dict)
    """
    response = Response(response, result_path)
    response.validate()
    result = response.result
    if require_unique and isinstance(result, list):
        elements_in_result = len(result)
        if elements_in_result > 1:
            exc_msg = f'Expected only one element in response, got {elements_in_result}'
            raise UnexpectedResponse(exc_msg)
        response = Response(result[0], return_path)
        response.validate()
    return response.result


class Response:

    def __init__(self, body, result_path='result'):
        self.error_code = body['errorCode'] if 'errorCode' in body else None
        self.error_cause = body['cause'] if 'cause' in body else body['errorCause'] if 'errorCause' in body else None
        self.result = self._find_result(body, result_path)

    def _find_result(self, body, result_path):
        try:
            result = self._get_by_dict_path(body, result_path) if result_path else body
            return result or {}
        except InvalidDictPath as e:
            raise UnexpectedResponse(f'No value under {result_path} in {body}') from e

    def validate(self):
        """
        Raise SoapApiError if error code is present.
        """
        if self.error_code and self.error_code.lower() != 'ok':
            raise SoapApiError(self.error_code, self.error_cause)

    @staticmethod
    def _get_by_dict_path(input_dict, result_path):
        """
        :param dict input_dict: e.g. {'a': {'b': {'c': 'my_value}}}
        :param string result_path: e.g. 'a.b'
        :return: whatever object is stored under given key, e.g. {'c': 'my_value'}
        """
        for key in result_path.split('.'):
            if input_dict is None:
                raise InvalidDictPath(f'Cannot parse path {result_path!r}. Failed on {key!r}')
            input_dict = input_dict[key]
        return input_dict


def remove_namespaces(element, as_string=False):
    """
    Remove namespaces from lxml.etree.Element

    :param lxml.etree.Element element:
    :param bool as_string: returns string if True
    :return: element without namespaces
    :rtype: string | lxml.etree.Element
    """
    root = element.getroottree().getroot()
    for elem in root.iter():
        if etree.QName(elem.tag).namespace:
            elem.tag = etree.QName(elem.tag).localname
        for attr in elem.attrib:
            if etree.QName(attr).namespace:
                elem.attrib[etree.QName(attr).localname] = elem.attrib[attr]
                del elem.attrib[attr]
    etree.cleanup_namespaces(root)
    return etree.tostring(root, pretty_print=True) if as_string else root


def convert_xml_to_dict(xml_input):
    return xmltodict.parse(xml_input, attr_prefix='', dict_constructor=dict)


def convert_metadata_response(response):
    """
    Convert response to a more readable format

    Example input:

        {
            'metaClass': 'com.nokia.srbts.mnl:LUAC',
            'metaVersion': 'MNL25R2_2503_101',
            'pDef': [
                {'name': 'webEMSessionLogoutTimer',
                 'propertyDefs': {
                     'propertyDef': [
                         {'#text': 'WebEM session logout timer', 'name': 'ui.name'},
                         {'#text': 'Description 3', 'name': 'ui.description'},
                         {'#text': '900', 'name': 'constraint.default'},
                         {'#text': 'mandatory', 'name': 'constraint.editing.create'},
                         {'#text': 'optional', 'name': 'constraint.editing.update'},
                         {'#text': 'Seconds', 'name': 'ui.unit'},
                         {'#text': '120', 'name': 'constraint.range.1.min'},
                         {'#text': '7200', 'name': 'constraint.range.1.max'},
                         {'#text': '1', 'name': 'constraint.range.1.step'},
                         {'#text': '1', 'name': 'ui.conversion.range.1.divisor'},
                         {'#text': '1', 'name': 'ui.conversion.range.1.multiplier'},
                         {'#text': '0.0', 'name': 'ui.conversion.range.1.shift'},
                         {'#text': '0', 'name': 'constraint.length.min'},
                         {'#text': '0', 'name': 'constraint.length.max'}]},
                 'type': 'Integer'}],
            'structListDef': {
                'itemDef': {
                    'pDef': {
                        'name': 'templateName',
                        'propertyDefs': {
                            'propertyDef': [
                                {'#text': 'Template name', 'name': 'ui.name'},
                                {'#text': 'Description 1', 'name': 'ui.description'},
                                {'#text': 'optional', 'name': 'constraint.editing.create'},
                                {'#text': 'optional', 'name': 'constraint.editing.update'},
                                {'#text': '0', 'name': 'constraint.length.min'},
                                {'#text': '255', 'name': 'constraint.length.max'}]},
                        'type': 'String'}},
                'name': 'configurationTemplates',
                'propertyDefs': {
                    'propertyDef': [
                        {'#text': 'Configuration templates', 'name': 'ui.name'},
                        {'#text': 'Description 2', 'name': 'ui.description'},
                        {'#text': '0', 'name': 'constraint.size.min'},
                        {'#text': '10', 'name': 'constraint.size.max'},
                        {'#text': 'optional', 'name': 'constraint.editing.create'},
                        {'#text': 'optional', 'name': 'constraint.editing.update'}
                    ]
                }
            }
        }

    Example output:

        {
            'metaClass': 'com.nokia.srbts.mnl:LUAC',
            'metaVersion': 'MNL25R2_2503_101',
            'pDef': {
                'webEMSessionLogoutTimer': {
                    'constraint.default': '900',
                    'constraint.editing.create': 'mandatory',
                    'constraint.editing.update': 'optional',
                    'constraint.length.max': '0',
                    'constraint.length.min': '0',
                    'constraint.range.1.max': '7200',
                    'constraint.range.1.min': '120',
                    'constraint.range.1.step': '1',
                    'type': 'Integer',
                    'ui.conversion.range.1.divisor': '1',
                    'ui.conversion.range.1.multiplier': '1',
                    'ui.conversion.range.1.shift': '0.0',
                    'ui.description': 'Description 3',
                    'ui.name': 'WebEM session logout timer',
                    'ui.unit': 'Seconds'
                }
            },
            'structListDef': {
                'configurationTemplates': {
                    'constraint.editing.create': 'optional',
                    'constraint.editing.update': 'optional',
                    'constraint.size.max': '10',
                    'constraint.size.min': '0',
                    'ui.description': 'Description 1',
                    'ui.name': 'Configuration templates',
                    'itemDef': {
                        'pDef': {
                            'templateName': {
                                'constraint.editing.create': 'optional',
                                'constraint.editing.update': 'optional',
                                'constraint.length.max': '255',
                                'constraint.length.min': '0',
                                'type': 'String',
                                'ui.description': 'Description 2',
                                'ui.name': 'Template name'
                            }
                        }
                    }
                }
            }
        }

    :param dict response: response to convert
    :return: converted response
    :rtype: dict | list
    """
    if isinstance(response, list):
        for item in response:
            convert_metadata_response(item)
    elif isinstance(response, dict):
        _convert_metadata_response(response)
    return response


def _convert_metadata_response(response):
    for key, value in response.items():
        if isinstance(value, dict):
            convert_metadata_response(value)
            new_defs = _convert_dict(value)
            if new_defs:
                response[key].update(new_defs)
        elif isinstance(value, list):
            convert_metadata_response(value)
            new_defs = _convert_list(value)
            if new_defs:
                response[key] = new_defs
    return response


def _convert_dict(dict_input):
    new_defs = {}
    new_def = _flatten_property_defs(dict_input)
    if new_def and 'name' in dict_input:
        new_defs.update({dict_input['name']: new_def})
        if 'type' in dict_input:
            new_defs[dict_input['name']].update({'type': dict_input['type']})
            del dict_input['type']
        del dict_input['name']
    return new_defs


def _convert_list(list_input):
    new_defs = {}
    for item in list_input:
        new_def = _flatten_property_defs(item)
        if new_def and 'name' in item:
            new_defs.update({item['name']: new_def})
            if 'type' in item:
                new_defs[item['name']].update({'type': item['type']})
    return new_defs


def _flatten_property_defs(dict_input):
    new_def = {}
    if 'propertyDefs' in dict_input and 'propertyDef' in dict_input['propertyDefs']:
        property_defs = dict_input['propertyDefs']['propertyDef']
        for item in property_defs:
            if 'name' in item and '#text' in item:
                new_def[item['name']] = item['#text']
        del dict_input['propertyDefs']
    if 'itemDef' in dict_input:
        new_def.update({'itemDef': dict_input['itemDef']})
        del dict_input['itemDef']
    return new_def
